sysauto_script.script:
(function ptagPdsTeamSync() {
    // Mirrors the ACTIVE members of "PDS Solution Consulting" into "PTAG Hub - PDS Team" (Jon, 2026-09-29).
    // Adds missing people, removes anyone who is no longer in the source group or is inactive.
    // Creates the target group on first run, so the job self-installs on every instance.
    var SOURCE = 'PDS Solution Consulting', TARGET = 'PTAG Hub - PDS Team';
    var src = new GlideRecord('sys_user_group');
    if (!src.get('name', SOURCE)) { gs.warn('PTAG PDS team sync: source group not found: ' + SOURCE); return; }
    var tgt = new GlideRecord('sys_user_group');
    if (!tgt.get('name', TARGET)) {
        tgt.initialize();
        tgt.setValue('name', TARGET);
        tgt.setValue('active', true);
        tgt.setValue('description', 'PDS team for PTAG Hub assignment. Members mirror "' + SOURCE +
            '" every 12 hours (scheduled job "PTAG Hub - PDS team membership sync"). Change membership in "' +
            SOURCE + '", not here: manual edits here are overwritten.');
        tgt.insert();
    }
    var want = {}, wantCount = 0;
    var m = new GlideRecord('sys_user_grmember');
    m.addQuery('group', src.getUniqueValue());
    m.addQuery('user.active', true);
    m.query();
    while (m.next()) { if (!want[m.getValue('user')]) { want[m.getValue('user')] = true; wantCount++; } }
    var have = {}, added = 0, removed = 0;
    var t = new GlideRecord('sys_user_grmember');
    t.addQuery('group', tgt.getUniqueValue());
    t.query();
    while (t.next()) {
        var u = t.getValue('user');
        if (!want[u] || have[u]) { t.deleteRecord(); removed++; } else { have[u] = true; }
    }
    for (var id in want) {
        if (!have[id]) {
            var n = new GlideRecord('sys_user_grmember');
            n.initialize();
            n.setValue('group', tgt.getUniqueValue());
            n.setValue('user', id);
            n.insert();
            added++;
        }
    }
    gs.info('PTAG PDS team sync: +' + added + ' -' + removed + ', members now ' + wantCount);
})();
